          "tooltip": {
            "signal": "{'IP': datum.cip.ip, 'Collected At (UTC)': datum.doc['@timestamp'], 'Inbound Risk': datum.cip.score ? datum.cip.score.inbound : null, 'Outbound Risk': datum.cip.score ? datum.cip.score.outbound : null}"
          }
